  // obras reales configuradas para la planta.
  const [obrasReales, setObrasReales] = useState([]);
  useEffect(() => {
    sbClient.from("obras_planta").select("obra").eq("planta", driver.planta).order("obra").then(({
      data
    }) => setObrasReales((data || []).map(o => o.obra)));
  }, [driver.planta]);
  const [servicio, setServicio] = useState("");
  const [subAlmuerzo, setSubAlmuerzo] = useState("");
  const [comentario, setComentario] = useState("");
  const [adjuntoServicio, setAdjuntoServicio] = useState(null);
  const [fallaMixer, setFallaMixer] = useState("");
  const [fallaTipos, setFallaTipos] = useState([]); // chips seleccionados (multi)
  const [fallaOtroTexto, setFallaOtroTexto] = useState(""); // texto libre si elige "Otro"
  const [fallaComent, setFallaComent] = useState("");
